-- Jawed Web Studio HQ — initial isolated D1 schema
-- Apply only to the dedicated database named jawed-studio-hq.
-- IDs are generated by the application (UUID strings).
-- Monetary values use integer minor units (e.g. paise for INR).
-- Archive fields implement soft deletion; do not hard-delete business records.

CREATE TABLE IF NOT EXISTS hq_users (
  uid TEXT PRIMARY KEY,
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  display_name TEXT,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','disabled')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  last_seen_at TEXT,
  CHECK (length(trim(email)) > 3)
);

CREATE TABLE IF NOT EXISTS clients (
  id TEXT PRIMARY KEY,
  client_code TEXT UNIQUE,
  name TEXT NOT NULL,
  business_name TEXT,
  status TEXT NOT NULL DEFAULT 'lead'
    CHECK (status IN ('lead','prospect','active','paused','completed','closed')),
  email TEXT,
  phone TEXT,
  website_url TEXT,
  billing_address TEXT,
  notes TEXT,
  source TEXT,
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  updated_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (length(trim(name)) > 0),
  CHECK ((archived_at IS NULL AND archived_by IS NULL) OR (archived_at IS NOT NULL AND archived_by IS NOT NULL))
);

CREATE TABLE IF NOT EXISTS client_contacts (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  full_name TEXT NOT NULL,
  role_title TEXT,
  email TEXT,
  phone TEXT,
  is_primary INTEGER NOT NULL DEFAULT 0 CHECK (is_primary IN (0,1)),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (length(trim(full_name)) > 0)
);

CREATE TABLE IF NOT EXISTS projects (
  id TEXT PRIMARY KEY,
  project_code TEXT UNIQUE,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  name TEXT NOT NULL,
  project_type TEXT NOT NULL DEFAULT 'business-website'
    CHECK (project_type IN ('business-website','portfolio','web-app','automation','ai-app','calculator-generator','maintenance','other')),
  status TEXT NOT NULL DEFAULT 'discovery'
    CHECK (status IN ('lead','discovery','quoted','approved','in-progress','review','blocked','completed','on-hold','cancelled')),
  priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','urgent')),
  summary TEXT,
  scope_markdown TEXT,
  start_date TEXT,
  target_date TEXT,
  completed_at TEXT,
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (length(currency) = 3),
  quoted_amount_minor INTEGER CHECK (quoted_amount_minor IS NULL OR quoted_amount_minor >= 0),
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  updated_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (length(trim(name)) > 0),
  CHECK (target_date IS NULL OR start_date IS NULL OR target_date >= start_date),
  CHECK ((archived_at IS NULL AND archived_by IS NULL) OR (archived_at IS NOT NULL AND archived_by IS NOT NULL))
);

CREATE TABLE IF NOT EXISTS project_milestones (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  name TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'not-started'
    CHECK (status IN ('not-started','in-progress','blocked','completed','skipped')),
  due_date TEXT,
  completed_at TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (length(trim(name)) > 0)
);

CREATE TABLE IF NOT EXISTS project_tasks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  milestone_id TEXT REFERENCES project_milestones(id) ON DELETE RESTRICT,
  title TEXT NOT NULL,
  description TEXT,
  status TEXT NOT NULL DEFAULT 'todo'
    CHECK (status IN ('todo','in-progress','blocked','done','cancelled')),
  priority TEXT NOT NULL DEFAULT 'normal' CHECK (priority IN ('low','normal','high','urgent')),
  assigned_to TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  due_date TEXT,
  completed_at TEXT,
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  updated_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (length(trim(title)) > 0)
);

CREATE TABLE IF NOT EXISTS repositories (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  provider TEXT NOT NULL DEFAULT 'github' CHECK (provider IN ('github','gitlab','other')),
  repository_full_name TEXT NOT NULL,
  repository_url TEXT NOT NULL,
  default_branch TEXT NOT NULL DEFAULT 'main',
  visibility TEXT CHECK (visibility IN ('public','private','internal')),
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  UNIQUE(project_id, provider, repository_full_name)
);

CREATE TABLE IF NOT EXISTS deployments (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  repository_id TEXT REFERENCES repositories(id) ON DELETE RESTRICT,
  environment TEXT NOT NULL CHECK (environment IN ('preview','staging','production')),
  status TEXT NOT NULL DEFAULT 'pending'
    CHECK (status IN ('pending','building','success','failed','rolled-back','cancelled')),
  branch_name TEXT,
  commit_sha TEXT,
  deployment_url TEXT,
  provider_deployment_id TEXT,
  initiated_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  deployed_at TEXT,
  verified_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  verified_at TEXT,
  verification_notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE IF NOT EXISTS approvals (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  deployment_id TEXT REFERENCES deployments(id) ON DELETE RESTRICT,
  approval_type TEXT NOT NULL
    CHECK (approval_type IN ('scope','design','content','qa','production-release','handover','other')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected','withdrawn')),
  requested_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  requested_from_email TEXT,
  decided_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  decision_note TEXT,
  requested_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  decided_at TEXT,
  evidence_url TEXT
);

CREATE TABLE IF NOT EXISTS qa_checks (
  id TEXT PRIMARY KEY,
  project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE RESTRICT,
  deployment_id TEXT REFERENCES deployments(id) ON DELETE RESTRICT,
  category TEXT NOT NULL
    CHECK (category IN ('functionality','responsive','accessibility','seo','performance','security','browser','content','backup','other')),
  check_name TEXT NOT NULL,
  result TEXT NOT NULL DEFAULT 'not-run' CHECK (result IN ('not-run','pass','fail','blocked','not-applicable')),
  evidence_url TEXT,
  notes TEXT,
  checked_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  checked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  CHECK (length(trim(check_name)) > 0)
);

CREATE TABLE IF NOT EXISTS quotations (
  id TEXT PRIMARY KEY,
  quote_number TEXT NOT NULL UNIQUE,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','sent','accepted','rejected','expired','withdrawn')),
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (length(currency) = 3),
  subtotal_minor INTEGER NOT NULL DEFAULT 0 CHECK (subtotal_minor >= 0),
  tax_minor INTEGER NOT NULL DEFAULT 0 CHECK (tax_minor >= 0),
  total_minor INTEGER NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
  valid_until TEXT,
  terms_markdown TEXT,
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS invoices (
  id TEXT PRIMARY KEY,
  invoice_number TEXT NOT NULL UNIQUE,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,
  quotation_id TEXT REFERENCES quotations(id) ON DELETE RESTRICT,
  status TEXT NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','issued','partially-paid','paid','overdue','void')),
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (length(currency) = 3),
  subtotal_minor INTEGER NOT NULL DEFAULT 0 CHECK (subtotal_minor >= 0),
  tax_minor INTEGER NOT NULL DEFAULT 0 CHECK (tax_minor >= 0),
  total_minor INTEGER NOT NULL DEFAULT 0 CHECK (total_minor >= 0),
  amount_paid_minor INTEGER NOT NULL DEFAULT 0 CHECK (amount_paid_minor >= 0),
  issued_on TEXT,
  due_on TEXT,
  notes TEXT,
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (amount_paid_minor <= total_minor)
);

CREATE TABLE IF NOT EXISTS payments (
  id TEXT PRIMARY KEY,
  invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE RESTRICT,
  amount_minor INTEGER NOT NULL CHECK (amount_minor > 0),
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (length(currency) = 3),
  payment_method TEXT CHECK (payment_method IN ('bank-transfer','upi','cash','card','other')),
  reference_number TEXT,
  paid_at TEXT NOT NULL,
  recorded_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  notes TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS maintenance_plans (
  id TEXT PRIMARY KEY,
  client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE RESTRICT,
  project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,
  name TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'proposed' CHECK (status IN ('proposed','active','paused','cancelled','expired')),
  billing_cycle TEXT NOT NULL DEFAULT 'monthly' CHECK (billing_cycle IN ('monthly','quarterly','half-yearly','yearly','one-time')),
  currency TEXT NOT NULL DEFAULT 'INR' CHECK (length(currency) = 3),
  fee_minor INTEGER NOT NULL DEFAULT 0 CHECK (fee_minor >= 0),
  starts_on TEXT,
  renews_on TEXT,
  ends_on TEXT,
  scope_markdown TEXT,
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS assets (
  id TEXT PRIMARY KEY,
  project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,
  client_id TEXT REFERENCES clients(id) ON DELETE RESTRICT,
  category TEXT NOT NULL
    CHECK (category IN ('brand','logo','image','document','prompt','template','snippet','sop','handover','backup-reference','other')),
  name TEXT NOT NULL,
  description TEXT,
  storage_provider TEXT CHECK (storage_provider IN ('github','r2','drive','url','other')),
  storage_key TEXT,
  external_url TEXT,
  mime_type TEXT,
  file_size_bytes INTEGER CHECK (file_size_bytes IS NULL OR file_size_bytes >= 0),
  version_label TEXT,
  is_sensitive INTEGER NOT NULL DEFAULT 0 CHECK (is_sensitive IN (0,1)),
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (length(trim(name)) > 0)
);

CREATE TABLE IF NOT EXISTS activity_notes (
  id TEXT PRIMARY KEY,
  client_id TEXT REFERENCES clients(id) ON DELETE RESTRICT,
  project_id TEXT REFERENCES projects(id) ON DELETE RESTRICT,
  note_type TEXT NOT NULL DEFAULT 'note'
    CHECK (note_type IN ('note','call','email','meeting','follow-up','decision','blocker')),
  subject TEXT,
  body TEXT NOT NULL,
  follow_up_at TEXT,
  created_by TEXT NOT NULL REFERENCES hq_users(uid) ON DELETE RESTRICT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  archived_at TEXT,
  archived_by TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  CHECK (client_id IS NOT NULL OR project_id IS NOT NULL)
);

CREATE TABLE IF NOT EXISTS audit_logs (
  id TEXT PRIMARY KEY,
  actor_uid TEXT REFERENCES hq_users(uid) ON DELETE RESTRICT,
  actor_email TEXT NOT NULL,
  action TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT,
  request_id TEXT,
  ip_hash TEXT,
  user_agent TEXT,
  before_json TEXT CHECK (before_json IS NULL OR json_valid(before_json)),
  after_json TEXT CHECK (after_json IS NULL OR json_valid(after_json)),
  metadata_json TEXT CHECK (metadata_json IS NULL OR json_valid(metadata_json)),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- Useful list, dashboard, and foreign-key lookup indexes.
CREATE INDEX IF NOT EXISTS idx_clients_status_active ON clients(status, archived_at, updated_at);
CREATE INDEX IF NOT EXISTS idx_contacts_client ON client_contacts(client_id, archived_at);
CREATE INDEX IF NOT EXISTS idx_projects_client_status ON projects(client_id, status, archived_at);
CREATE INDEX IF NOT EXISTS idx_projects_dashboard ON projects(status, target_date, archived_at);
CREATE INDEX IF NOT EXISTS idx_milestones_project ON project_milestones(project_id, status, due_date);
CREATE INDEX IF NOT EXISTS idx_tasks_project_status ON project_tasks(project_id, status, due_date, archived_at);
CREATE INDEX IF NOT EXISTS idx_tasks_assignee ON project_tasks(assigned_to, status, due_date);
CREATE INDEX IF NOT EXISTS idx_repositories_project ON repositories(project_id, archived_at);
CREATE INDEX IF NOT EXISTS idx_deployments_project_time ON deployments(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_approvals_status_time ON approvals(status, requested_at DESC);
CREATE INDEX IF NOT EXISTS idx_qa_project_result ON qa_checks(project_id, result, category);
CREATE INDEX IF NOT EXISTS idx_quotations_client_status ON quotations(client_id, status, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_invoices_client_status ON invoices(client_id, status, due_on);
CREATE INDEX IF NOT EXISTS idx_payments_invoice_time ON payments(invoice_id, paid_at DESC);
CREATE INDEX IF NOT EXISTS idx_maintenance_client_status ON maintenance_plans(client_id, status, renews_on);
CREATE INDEX IF NOT EXISTS idx_assets_project_category ON assets(project_id, category, archived_at);
CREATE INDEX IF NOT EXISTS idx_activity_client_time ON activity_notes(client_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_activity_project_time ON activity_notes(project_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_entity_time ON audit_logs(entity_type, entity_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_audit_actor_time ON audit_logs(actor_uid, created_at DESC);

-- Audit history is append-only.
CREATE TRIGGER IF NOT EXISTS trg_audit_logs_no_update
BEFORE UPDATE ON audit_logs BEGIN
  SELECT RAISE(ABORT, 'audit_logs are append-only');
END;

CREATE TRIGGER IF NOT EXISTS trg_audit_logs_no_delete
BEFORE DELETE ON audit_logs BEGIN
  SELECT RAISE(ABORT, 'audit_logs are append-only');
END;
